/// <summary>
/// Continuing permission notice report controller
/// </summary>
class METContinuingPermissionNoticeController extends SrsReportRunController
{

}

Method.Source:
    // ** WIP, continuing permission notice requirements tbd.
    // Report may end up being generated externally.

    /// <summary>
    /// Entry point
    /// </summary>
    /// <param name = "_args">_args</param>
    static void main(Args _args)
    {
        METContinuingPermissionNoticeController controller;

        controller = new METContinuingPermissionNoticeController();
        controller.parmReportName(ssrsReportStr(METContinuingPermissionNotice, Report));
        controller.parmDialogCaption("Continuing permission notice");
        controller.parmArgs(_args);

        METContinuingPermissionNoticeContract contract = controller.parmReportContract().parmRdpContract();
        controller.startOperation();
    }
